INSERT INTO portraits(id,payload,published) VALUES ('different-glasses','{"id":"different-glasses","name_ko":"가끔은 평소와 다른 안경으로","name_ja":"たまにはいつもと違うメガネで","rarity":5,"image_url":"/images/portrait-different-glasses-source.jpg","thumbnail_url":"","source_image":"/images/portrait-different-glasses-source.jpg","source_url":"","source_note":"사용자가 제공한 인게임 화면. 이름의 강화 표기는 제외했습니다. 현재 이미지는 화면 원본이며 전용 포트레이트 이미지로 교체할 수 있습니다.","verification":"인게임 화면 초벌 전사 · 이름·수치 검토 대기","stats_max":{"HP":191,"공격력":215,"방어력":368},"ability_levels":[{"level":0,"effects":[]},{"level":1,"effects":[]},{"level":2,"effects":[]},{"level":3,"effects":[]},{"level":4,"effects":[]},{"level":5,"effects":[{"text_ko":"MP 회복 효율 +15%","text_ja":"MP回復効率+15%","tags":["MP 회복 효율"],"condition_ko":"","condition_ja":""}]}]}',1) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,published=excluded.published;
